def to_bn(num_str):
    bn_digits = {'0':'০', '1':'১', '2':'২', '3':'৩', '4':'৪', '5':'৫', '6':'৬', '7':'৭', '8':'৮', '9':'৯'}
    res = ''
    for ch in str(num_str):
        res += bn_digits.get(ch, ch)
    suffix_map = {
        'A':'ক', 'B':'খ', 'C':'গ', 'D':'ঘ', 'E':'ঙ', 'F':'চ', 'G':'ছ', 'H':'জ', 'I':'ঝ', 
        '-I':'ঝ', '-i':'ঝ', 'J':'ঞ', 'K':'ট', 'L':'ঠ', 'M':'ড', 'N':'ঢ'
    }
    for eng, bn in suffix_map.items():
        if res.endswith(eng):
            res = res[:-len(eng)] + bn
    return res

